$ErrorActionPreference='Stop';$root=Split-Path -Parent $MyInvocation.MyCommand.Path;$solutionRoot=Join-Path $root 'solutions';$pass=0;$fail=0
Get-ChildItem -LiteralPath $solutionRoot -Directory|Sort-Object Name|ForEach-Object{$dir=$_.FullName;Push-Location $dir;try{Get-ChildItem -Path $dir -Recurse -File -Filter '*.class'|Remove-Item -Force -ErrorAction SilentlyContinue;& javac --release 17 Main.java SelfCheck.java;if($LASTEXITCODE-ne 0){throw 'compile failed'};$o=& java SelfCheck 2>&1;if($LASTEXITCODE-ne 0-or($o-notmatch 'PASS')){throw($o-join [Environment]::NewLine)};Write-Output "PASS $($_.Name)";$pass++}catch{Write-Output "FAIL $($_.Name) : $($_.Exception.Message)";$fail++}finally{Get-ChildItem -Path $dir -Recurse -File -Filter '*.class'|Remove-Item -Force -ErrorAction SilentlyContinue;Pop-Location}}
Write-Output "Summary: PASS=$pass FAIL=$fail";if($fail-ne 0){exit 1}
